#!/usr/bin/env bash
# Question 1: Deployment ${Q1_APP} not running. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q1_APP}
  namespace: ${Q1_NS}
  labels: { app: ${Q1_APP} }
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q1_APP} }
  template:
    metadata:
      labels: { app: ${Q1_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          resources:
            requests: { cpu: 100m, memory: 64Mi }
EOF
kubectl -n "${Q1_NS}" get deployment "${Q1_APP}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q1.uid"
chmod 644 "/var/tmp/cka-q1.uid"

case "${Q1_FAULT}" in
  priority-class)
    kubectl -n "${Q1_NS}" patch deployment "${Q1_APP}" -p '{"spec":{"template":{"spec":{"priorityClassName":"critical-batch"}}}}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q1_NS}" scale "deployment/${Q1_APP}" --replicas=2
notready=0
for _ in $(seq 1 8); do
  states="$(kubectl -n "${Q1_NS}" get pods -l "app=${Q1_APP}" -o jsonpath='{range .items[*]}{.status.phase} {.status.conditions[?(@.type=="Ready")].status} {.status.conditions[?(@.type=="PodScheduled")].status} {.status.containerStatuses[0].state.waiting.reason} {.status.containerStatuses[0].restartCount}{"\n"}{end}' 2>/dev/null)"
  if grep -qE '(ErrImagePull|ImagePullBackOff|CrashLoopBackOff|CreateContainerConfigError|CreateContainerError|RunContainerError)|[1-9][0-9]*$|^[A-Za-z]+ [A-Za-z]* False' <<< "$states"; then break; fi
  if kubectl -n "${Q1_NS}" get events --field-selector reason=FailedMount -o name 2>/dev/null | grep -q .; then break; fi
  if grep -qE '^Running False' <<< "$states"; then
    notready=$((notready + 1))
    (( notready >= 3 )) && break
  else
    notready=0
  fi
  sleep 2
done
[[ "$(kubectl -n "${Q1_NS}" get deployment "${Q1_APP}" -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "${Q1_APP} still runs 2 replicas" >&2; exit 1; }
